mapper.select:
SELECT  #{start} time,area_id area,ip_addr IP,SUM(c2s_byte_len)+SUM(s2c_byte_len) COUNT
FROM traffic_ip_active_statistic

   WHERE stat_time >= #{start}
   AND stat_time < #{end}

GROUP BY ip_addr ,area_id
ORDER BY COUNT desc
LIMIT 10;


select #{start} time,CONVERT((sum(INOCTETS+OUTOCTETS))/300/2048,int) count
from traffic_netflow_port_info
GROUP BY RECV_TIME
HAVING RECV_TIME>= #{start}
and RECV_TIME< #{end};

select stat_time
  FROM traffic_ip_active_statistic

  WHERE stat_time < #{end}

  ORDER BY stat_time desc
  LIMIT 1;

select RECV_TIME
FROM traffic_netflow_port_info

  WHERE RECV_TIME < #{end}
  ORDER BY RECV_TIME desc
  LIMIT 1;
